/* source: js/utils/compat.js */
function deepClone(value) {
  return JSON.parse(JSON.stringify(value));
}

function last(array, fallback) {
  return array && array.length ? array[array.length - 1] : fallback;
}

function observeResize(element, callback) {
  if (typeof ResizeObserver !== 'undefined') {
    const observer = new ResizeObserver(function () { callback(); });
    observer.observe(element);
    return function () { observer.disconnect(); };
  }

  let frame = null;
  const handler = function () {
    if (frame !== null) cancelAnimationFrame(frame);
    frame = requestAnimationFrame(function () {
      frame = null;
      callback();
    });
  };
  window.addEventListener('resize', handler, { passive: true });
  return function () {
    if (frame !== null) cancelAnimationFrame(frame);
    window.removeEventListener('resize', handler);
  };
}

function readStorage(key, fallback) {
  try {
    const value = window.localStorage.getItem(key);
    return value === null ? fallback : value;
  } catch (error) {
    return fallback;
  }
}

function writeStorage(key, value) {
  try {
    window.localStorage.setItem(key, value);
  } catch (error) {
    // Storage can be unavailable in private/file contexts. The app remains usable.
  }
}

function dispatchAppEvent(name, detail) {
  let event;
  if (typeof CustomEvent === 'function') {
    event = new CustomEvent(name, { detail: detail });
  } else {
    event = document.createEvent('CustomEvent');
    event.initCustomEvent(name, false, false, detail);
  }
  document.dispatchEvent(event);
}


/* source: js/utils/math.js */
const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
const lerp = (a, b, t) => a + (b - a) * t;
const safeNumber = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
const mphToMps = mph => mph * 0.44704;
const rad = deg => deg * Math.PI / 180;

function interp1(xs, ys, x) {
  if (!xs || !ys || !xs.length || xs.length !== ys.length) return NaN;
  if (x <= xs[0]) return ys[0];
  if (x >= xs[xs.length - 1]) return ys[ys.length - 1];
  let lo = 0;
  let hi = xs.length - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (xs[mid] <= x) lo = mid; else hi = mid;
  }
  const span = xs[hi] - xs[lo];
  return span === 0 ? ys[lo] : lerp(ys[lo], ys[hi], (x - xs[lo]) / span);
}

function rms(values) {
  if (!values.length) return NaN;
  return Math.sqrt(values.reduce((sum, v) => sum + v * v, 0) / values.length);
}

function nearestIndex(sorted, target) {
  if (!sorted.length) return -1;
  let lo = 0, hi = sorted.length - 1;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (sorted[mid] < target) lo = mid + 1; else hi = mid;
  }
  if (lo === 0) return 0;
  return Math.abs(sorted[lo] - target) < Math.abs(sorted[lo - 1] - target) ? lo : lo - 1;
}


/* source: js/utils/export.js */
function downloadJson(filename, data) {
  downloadBlob(filename, JSON.stringify(data, null, 2), 'application/json;charset=utf-8');
}

function downloadResultsCsv(filename, result) {
  const o = result.out;
  const keys = ['timeS','speedMph','requestedPackPowerKW','actualPackPowerKW','packVoltageV','packCurrentA','cellVoltageV','cellCurrentA','cRate','soc','temperatureC','soh','ocvV','xn','xp','generatedHeatWCell','platingRisk','agingStress','powerLimited'];
  const headers = ['time_s','speed_mph','requested_pack_power_kW','actual_pack_power_kW','pack_voltage_V','pack_current_A','cell_voltage_V','cell_current_A','c_rate','soc_fraction','temperature_C','soh_fraction','ocv_V','negative_stoichiometry','positive_stoichiometry','cell_heat_W','plating_risk_index','aging_stress_index','power_limited'];
  const rows = [headers.join(',')];
  for (let i=0;i<o.timeS.length;i++) rows.push(keys.map(k => csvValue(o[k][i])).join(','));
  downloadBlob(filename, rows.join('\n'), 'text/csv;charset=utf-8');
}

function csvValue(v) { return Number.isFinite(v) ? String(v) : ''; }
function downloadBlob(filename, content, type) {
  const url = URL.createObjectURL(new Blob([content], { type }));
  const a = document.createElement('a'); a.href=url; a.download=filename; document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(url),1000);
}


/* source: js/core/electrochem.js */

const lfpPositiveEntropicX = [0,0.05,0.1,0.15,0.2,0.25,0.3,0.35,0.4,0.45,0.5,0.55,0.6,0.65,0.7,0.75,0.8,0.85,0.9,0.95,1];
const lfpPositiveEntropicY = [0.0001,4.7145e-5,3.7666e-5,2.0299e-5,5.9833e-6,-4.6859e-6,-1.3966e-5,-2.3528e-5,-3.3593e-5,-4.3433e-5,-5.2311e-5,-6.0211e-5,-6.8006e-5,-7.6939e-5,-8.7641e-5,-9.913e-5,-0.00010855,-0.00011266,-0.00011238,-0.00010921,-0.00022539];

function nmcNegativeOcp(x) {
  return 9.47057878e-1 * Math.exp(-1.59418743e2 * x)
    - 3.50928033e4
    + 1.64230269e-1 * Math.tanh(-4.55509094e1 * (x - 3.24116012e-2))
    + 3.69968491e-2 * Math.tanh(-1.96718868e1 * (x - 1.68334476e-1))
    + 1.91517003e4 * Math.tanh(3.19648312 * (x - 1.85139824))
    + 5.42448511e4 * Math.tanh(-3.19009848 * (x - 2.01660395));
}

function nmcPositiveOcp(x) {
  return -3.04420906 * x + 10.04892207
    - 0.65637536 * Math.tanh(-4.02134095 * (x - 0.80063948))
    + 4.24678547 * Math.tanh(12.17805062 * (x - 7.57659337))
    - 0.3757068 * Math.tanh(59.33067782 * (x - 0.99784492));
}

function lfpGraphiteNegativeOcp(x) {
  return 5.29210878e1 * Math.exp(-1.72699386e2 * x)
    - 1.17963399e3
    + 1.20956356e3 * Math.tanh(6.72033948e1 * (x + 2.44746396e-2))
    + 4.52430314e-2 * Math.tanh(-1.47542326e1 * (x - 1.62746053e-1))
    + 2.018558e1 * Math.tanh(-2.46666302e1 * (x - 1.12986136))
    + 2.01708039e-2 * Math.tanh(-1.19900231e1 * (x - 5.4977344e-1))
    + 4.99616805e1 * Math.tanh(-6.11370883e1 * (x + 4.69382558e-3));
}

function lfpPositiveOcp(x) {
  return 3.41285712 - 1.49721852e-2 * x
    + 3.54866018e14 * Math.exp(-3.95729493e2 * x)
    - 1.45998465 * Math.exp(-1.10108622e2 * (1 - x));
}

function graphiteEntropic(x) {
  return (-0.1112 * x + 0.02914 + 0.3561 * Math.exp(-((x - 0.08309) ** 2) / 0.004616)) / 1000;
}

const ocpModels = {
  ae_nmc_negative: nmcNegativeOcp,
  ae_nmc_positive: nmcPositiveOcp,
  ae_lfp_graphite_negative: lfpGraphiteNegativeOcp,
  ae_lfp_positive: lfpPositiveOcp
};

const entropicModels = {
  ae_graphite_entropic: graphiteEntropic,
  ae_nmc_positive_entropic: () => -1e-4,
  ae_lfp_positive_entropic: x => interp1(lfpPositiveEntropicX, lfpPositiveEntropicY, x)
};

function electrodeStoichiometry(cell, soc) {
  const z = clamp(soc, 0, 1);
  const xn = cell.negative.stoichMin + z * (cell.negative.stoichMax - cell.negative.stoichMin);
  const xp = cell.positive.stoichMax - z * (cell.positive.stoichMax - cell.positive.stoichMin);
  return { xn, xp };
}

function electrochemicalState(cell, soc) {
  const { xn, xp } = electrodeStoichiometry(cell, soc);
  const un = ocpModels[cell.negative.ocpModel](xn);
  const up = ocpModels[cell.positive.ocpModel](xp);
  const dunDT = entropicModels[cell.negative.entropicModel](xn);
  const dupDT = entropicModels[cell.positive.entropicModel](xp);
  return {
    xn,
    xp,
    negativeOcpV: un,
    positiveOcpV: up,
    ocvV: up - un,
    dOcvdTK: dupDT - dunDT,
    negativeLithiation: clamp((xn - cell.negative.stoichMin) / (cell.negative.stoichMax - cell.negative.stoichMin), 0, 1),
    positiveLithiation: clamp((xp - cell.positive.stoichMin) / (cell.positive.stoichMax - cell.positive.stoichMin), 0, 1)
  };
}


/* source: js/core/ecm.js */

function createEcmState() {
  return { v1: 0, v2: 0 };
}

function resistanceScale(prior, soc, temperatureK, soh = 1) {
  const lowTempDelta = Math.max(0, 298.15 - temperatureK);
  const highTempDelta = Math.max(0, temperatureK - 298.15);
  const tempScale = Math.exp(prior.temperatureResistanceCoeffPerK * lowTempDelta - 0.004 * highTempDelta);
  const edgeScale = 1
    + 0.62 * Math.exp(-clamp(soc, 0, 1) / 0.075)
    + 0.15 * Math.exp(-(1 - clamp(soc, 0, 1)) / 0.08);
  const healthScale = 1 + 1.8 * Math.max(0, 1 - soh);
  return clamp(tempScale * edgeScale * healthScale, 0.55, 6);
}

function ecmResistances(prior, soc, temperatureK, soh = 1) {
  const scale = resistanceScale(prior, soc, temperatureK, soh);
  return {
    r0: prior.ecm.r0Ohm * scale,
    r1: prior.ecm.r1Ohm * scale,
    r2: prior.ecm.r2Ohm * scale,
    tau1: prior.ecm.tau1S,
    tau2: prior.ecm.tau2S,
    scale
  };
}

function terminalVoltage(ocvV, currentA, state, resistance) {
  return ocvV - currentA * resistance.r0 - state.v1 - state.v2;
}

function advanceEcm(state, currentA, resistance, dt) {
  const a1 = Math.exp(-dt / Math.max(1e-6, resistance.tau1));
  const a2 = Math.exp(-dt / Math.max(1e-6, resistance.tau2));
  state.v1 = state.v1 * a1 + currentA * resistance.r1 * (1 - a1);
  state.v2 = state.v2 * a2 + currentA * resistance.r2 * (1 - a2);
  return state;
}


/* source: js/core/thermal.js */
function thermalCapacityJperK(cell) {
  return cell.specificHeatJkgK * cell.densityKgM3 * cell.volumeM3;
}

function heatRates({ currentA, ocvV, terminalVoltageV, temperatureK, dOcvdTK }) {
  const irreversibleW = currentA * (ocvV - terminalVoltageV);
  const reversibleW = -currentA * temperatureK * dOcvdTK;
  return { irreversibleW, reversibleW, generatedW: irreversibleW + reversibleW };
}

function advanceThermal({ cell, temperatureK, ambientK, generatedW, heatTransferCoeffWm2K, dt }) {
  const cth = thermalCapacityJperK(cell);
  const coolingW = heatTransferCoeffWm2K * cell.externalSurfaceAreaM2 * (temperatureK - ambientK);
  const dT = (generatedW - coolingW) * dt / Math.max(cth, 1e-9);
  return { temperatureK: temperatureK + dT, coolingW, thermalCapacityJperK: cth };
}


/* source: js/core/degradation.js */

function createAgingState(initialSoh = 1) {
  return { soh: clamp(initialSoh, 0.5, 1), efc: 0, damage: 0 };
}

function advanceAging(state, { prior, currentA, capacityAh, temperatureK, soc, dt, enabled }) {
  const cRate = Math.abs(currentA) / Math.max(capacityAh, 1e-9);
  const efcIncrement = Math.abs(currentA) * dt / (2 * 3600 * Math.max(capacityAh, 1e-9));
  state.efc += efcIncrement;

  const charge = currentA < 0;
  const lowTemperatureFactor = clamp((288.15 - temperatureK) / 20, 0, 1.5);
  const highSocFactor = clamp((soc - 0.75) / 0.25, 0, 1);
  const highChargeFactor = clamp((cRate - 0.5) / 1.5, 0, 1.5);
  const platingRisk = clamp((charge ? 1 : 0) * lowTemperatureFactor * highSocFactor * highChargeFactor * 100, 0, 100);

  const thermalStress = Math.exp((temperatureK - 298.15) / prior.aging.temperatureScaleK);
  const highSocStress = 1 + prior.aging.highSocWeight * Math.max(0, (soc - 0.7) / 0.3) ** 2;
  const cRateStress = 1 + prior.aging.highCRateWeight * Math.max(0, cRate - 1) ** 1.25;
  const stressIndex = clamp(25 * thermalStress * highSocStress * cRateStress, 0, 100);

  if (enabled) {
    const damageIncrement = prior.aging.damagePerEfc * efcIncrement * thermalStress * highSocStress * cRateStress;
    state.damage += damageIncrement;
    state.soh = clamp(state.soh - damageIncrement, 0.5, 1);
  }

  return { state, cRate, platingRisk, stressIndex };
}


/* source: js/core/pack.js */

function nominalPack(cell, prior, seriesCount, parallelCount) {
  return {
    nominalVoltageV: prior.nominalVoltageV * seriesCount,
    nominalCapacityAh: cell.capacityAh * parallelCount,
    nominalEnergyKWh: prior.nominalVoltageV * seriesCount * cell.capacityAh * parallelCount / 1000,
    cellCount: seriesCount * parallelCount
  };
}

function solveCellCurrentForPackPower({ requestedPowerW, seriesCount, parallelCount, baseCellVoltageV, r0Ohm, cell, prior }) {
  const nsnp = Math.max(1, seriesCount * parallelCount);
  const pPerCellW = requestedPowerW / nsnp;
  let currentA;
  let powerLimited = false;

  if (Math.abs(r0Ohm) < 1e-12) {
    currentA = pPerCellW / Math.max(0.1, baseCellVoltageV);
  } else {
    let disc = baseCellVoltageV * baseCellVoltageV - 4 * r0Ohm * pPerCellW;
    if (disc < 0) {
      disc = 0;
      powerLimited = true;
    }
    currentA = (baseCellVoltageV - Math.sqrt(disc)) / (2 * r0Ohm);
  }

  const maxDischargeA = prior.limits.maxDischargeC * cell.capacityAh;
  const maxChargeA = prior.limits.maxChargeC * cell.capacityAh;
  const limitedByCurrent = currentA > maxDischargeA || currentA < -maxChargeA;
  currentA = clamp(currentA, -maxChargeA, maxDischargeA);

  // Enforce terminal-voltage limits using the instantaneous R0 branch.
  const currentAtLower = (baseCellVoltageV - cell.lowerVoltageV) / Math.max(r0Ohm, 1e-9);
  const currentAtUpper = (baseCellVoltageV - cell.upperVoltageV) / Math.max(r0Ohm, 1e-9);
  if (currentA > currentAtLower) { currentA = Math.max(0, currentAtLower); powerLimited = true; }
  if (currentA < currentAtUpper) { currentA = Math.min(0, currentAtUpper); powerLimited = true; }

  const cellVoltageV = baseCellVoltageV - currentA * r0Ohm;
  const actualPowerW = seriesCount * parallelCount * currentA * cellVoltageV;
  return {
    currentA,
    cellVoltageV,
    packCurrentA: currentA * parallelCount,
    actualPowerW,
    unmetPowerW: requestedPowerW - actualPowerW,
    powerLimited: powerLimited || limitedByCurrent,
    limitedByCurrent
  };
}


/* source: js/core/vehicle.js */

const G = 9.80665;
const RHO_AIR = 1.225;

function accelerationAt(speedMps, index, dt = 1) {
  if (speedMps.length < 2) return 0;
  if (index <= 0) return (speedMps[1] - speedMps[0]) / dt;
  if (index >= speedMps.length - 1) return (speedMps[index] - speedMps[index - 1]) / dt;
  return (speedMps[index + 1] - speedMps[index - 1]) / (2 * dt);
}

function vehiclePowerDemand(vehicle, speedMps, accelerationMps2) {
  const grade = Math.atan(vehicle.gradePct / 100);
  const mEq = vehicle.massKg * vehicle.rotatingMassFactor;
  const inertialN = mEq * accelerationMps2;
  const rollingN = vehicle.massKg * G * vehicle.cRr * Math.cos(grade);
  const gradeN = vehicle.massKg * G * Math.sin(grade);
  const aeroN = 0.5 * RHO_AIR * vehicle.cd * vehicle.frontalAreaM2 * speedMps * speedMps;
  const wheelForceN = inertialN + rollingN + gradeN + aeroN;
  const wheelPowerW = wheelForceN * speedMps;

  let batteryPowerW;
  if (wheelPowerW >= 0) {
    batteryPowerW = wheelPowerW / Math.max(0.01, vehicle.driveEfficiency) + vehicle.auxPowerKW * 1000;
  } else {
    const regenW = Math.max(wheelPowerW * vehicle.regenEfficiency, -vehicle.maxRegenKW * 1000);
    batteryPowerW = regenW + vehicle.auxPowerKW * 1000;
  }
  batteryPowerW = Math.min(batteryPowerW, vehicle.maxTractionKW * 1000 + vehicle.auxPowerKW * 1000);
  return { wheelForceN, wheelPowerW, batteryPowerW, inertialN, rollingN, gradeN, aeroN };
}

function us06Profile(us06) {
  const speedMph = us06.speedMph;
  return {
    dt: us06.samplePeriodS,
    timeS: speedMph.map((_, i) => i * us06.samplePeriodS),
    speedMph,
    speedMps: speedMph.map(mphToMps)
  };
}


/* source: js/core/simulator.js */

function makeGenericProfile(durationS, dt) {
  const n = Math.floor(durationS / dt) + 1;
  return { dt, timeS: Array.from({ length: n }, (_, i) => i * dt), speedMph: Array(n).fill(0), speedMps: Array(n).fill(0) };
}

function simulate(config, datasets) {
  const cell = datasets.cells.find(c => c.id === config.cellId);
  if (!cell) throw new Error(`Unknown cell preset: ${config.cellId}`);
  const prior = datasets.priors[cell.id];
  if (!prior) throw new Error(`No reduced-order prior for: ${cell.id}`);

  const seriesCount = Math.max(1, Math.round(config.pack.series));
  const parallelCount = Math.max(1, Math.round(config.pack.parallel));
  const packNominal = nominalPack(cell, prior, seriesCount, parallelCount);

  let profile;
  if (config.scenario.type === 'us06') profile = us06Profile(datasets.us06);
  else if (config.scenario.type === 'reference-1c') profile = makeGenericProfile(cell.id.includes('nmc') ? 3700 : 3600, 1);
  else profile = makeGenericProfile(config.scenario.durationS, config.scenario.dtS || 1);

  let soc = clamp(config.initialSoc, 0.001, 0.999);
  let temperatureK = config.thermal.initialTempC + 273.15;
  const ambientK = config.thermal.ambientTempC + 273.15;
  const ecm = createEcmState();
  const aging = createAgingState(config.initialSoh === undefined ? 1 : config.initialSoh);
  let netEnergyKWh = 0;
  let dischargedEnergyKWh = 0;
  let recoveredEnergyKWh = 0;
  let cutoff = false;

  const out = {
    timeS: [], speedMph: [], speedMps: [], accelerationMps2: [],
    requestedPackPowerKW: [], actualPackPowerKW: [], unmetPackPowerKW: [],
    packVoltageV: [], packCurrentA: [], cellVoltageV: [], cellCurrentA: [], cRate: [],
    soc: [], temperatureC: [], soh: [], efc: [],
    ocvV: [], positiveOcpV: [], negativeOcpV: [], xn: [], xp: [],
    irreversibleHeatWCell: [], reversibleHeatWCell: [], generatedHeatWCell: [], coolingWCell: [],
    resistanceMOhmCell: [], platingRisk: [], agingStress: [], powerLimited: [], cutoff: []
  };

  for (let i = 0; i < profile.timeS.length; i++) {
    const dt = i === 0 ? profile.dt : Math.max(1e-6, profile.timeS[i] - profile.timeS[i - 1]);
    const electro = electrochemicalState(cell, soc);
    const resistance = ecmResistances(prior, soc, temperatureK, aging.soh);
    const baseCellVoltageV = electro.ocvV - ecm.v1 - ecm.v2;

    let requestedPowerW = 0;
    let currentA = 0;
    let packCurrentA = 0;
    let actualPowerW = 0;
    let unmetPowerW = 0;
    let cellVoltageV;
    let powerLimited = false;
    let accelerationMps2 = 0;

    if (!cutoff && config.scenario.type === 'us06') {
      accelerationMps2 = accelerationAt(profile.speedMps, i, profile.dt);
      const demand = vehiclePowerDemand(config.vehicle, profile.speedMps[i], accelerationMps2);
      requestedPowerW = demand.batteryPowerW;
      const solved = solveCellCurrentForPackPower({ requestedPowerW, seriesCount, parallelCount, baseCellVoltageV, r0Ohm: resistance.r0, cell, prior });
      ({ currentA, packCurrentA, actualPowerW, unmetPowerW, cellVoltageV, powerLimited } = solved);
    } else if (!cutoff && config.scenario.type === 'constant-power') {
      requestedPowerW = config.scenario.powerKW * 1000;
      const solved = solveCellCurrentForPackPower({ requestedPowerW, seriesCount, parallelCount, baseCellVoltageV, r0Ohm: resistance.r0, cell, prior });
      ({ currentA, packCurrentA, actualPowerW, unmetPowerW, cellVoltageV, powerLimited } = solved);
    } else if (!cutoff) {
      const requestedC = config.scenario.type === 'reference-1c' ? 1 : config.scenario.currentC;
      const maxDischargeA = prior.limits.maxDischargeC * cell.capacityAh;
      const maxChargeA = prior.limits.maxChargeC * cell.capacityAh;
      currentA = clamp(requestedC * cell.capacityAh, -maxChargeA, maxDischargeA);
      powerLimited = Math.abs(currentA - requestedC * cell.capacityAh) > 1e-9;
      cellVoltageV = terminalVoltage(electro.ocvV, currentA, ecm, resistance);
      if (cellVoltageV <= cell.lowerVoltageV && currentA > 0) { currentA = 0; cellVoltageV = baseCellVoltageV; cutoff = true; }
      if (cellVoltageV >= cell.upperVoltageV && currentA < 0) { currentA = 0; cellVoltageV = baseCellVoltageV; cutoff = true; }
      packCurrentA = currentA * parallelCount;
      actualPowerW = seriesCount * parallelCount * currentA * cellVoltageV;
      requestedPowerW = actualPowerW;
    }

    if (cellVoltageV === undefined) cellVoltageV = terminalVoltage(electro.ocvV, currentA, ecm, resistance);
    const packVoltageV = cellVoltageV * seriesCount;
    const heat = heatRates({ currentA, ocvV: electro.ocvV, terminalVoltageV: cellVoltageV, temperatureK, dOcvdTK: electro.dOcvdTK });
    const thermal = advanceThermal({ cell, temperatureK, ambientK, generatedW: heat.generatedW, heatTransferCoeffWm2K: config.thermal.hWm2K, dt });
    const agingStep = advanceAging(aging, { prior, currentA, capacityAh: cell.capacityAh, temperatureK, soc, dt, enabled: config.aging.enabled });

    out.timeS.push(profile.timeS[i]);
    out.speedMph.push(profile.speedMph[i] === undefined ? 0 : profile.speedMph[i]);
    out.speedMps.push(profile.speedMps[i] === undefined ? 0 : profile.speedMps[i]);
    out.accelerationMps2.push(accelerationMps2);
    out.requestedPackPowerKW.push(requestedPowerW / 1000);
    out.actualPackPowerKW.push(actualPowerW / 1000);
    out.unmetPackPowerKW.push(unmetPowerW / 1000);
    out.packVoltageV.push(packVoltageV);
    out.packCurrentA.push(packCurrentA);
    out.cellVoltageV.push(cellVoltageV);
    out.cellCurrentA.push(currentA);
    out.cRate.push(agingStep.cRate);
    out.soc.push(soc);
    out.temperatureC.push(temperatureK - 273.15);
    out.soh.push(aging.soh);
    out.efc.push(aging.efc);
    out.ocvV.push(electro.ocvV);
    out.positiveOcpV.push(electro.positiveOcpV);
    out.negativeOcpV.push(electro.negativeOcpV);
    out.xn.push(electro.xn);
    out.xp.push(electro.xp);
    out.irreversibleHeatWCell.push(heat.irreversibleW);
    out.reversibleHeatWCell.push(heat.reversibleW);
    out.generatedHeatWCell.push(heat.generatedW);
    out.coolingWCell.push(thermal.coolingW);
    out.resistanceMOhmCell.push(resistance.r0 * 1000);
    out.platingRisk.push(agingStep.platingRisk);
    out.agingStress.push(agingStep.stressIndex);
    out.powerLimited.push(powerLimited ? 1 : 0);
    out.cutoff.push(cutoff ? 1 : 0);

    if (i < profile.timeS.length - 1) {
      const effectiveCapacityAh = Math.max(cell.capacityAh * aging.soh, cell.capacityAh * 0.5);
      soc = clamp(soc - currentA * dt / (3600 * effectiveCapacityAh), 0, 1);
      temperatureK = thermal.temperatureK;
      advanceEcm(ecm, currentA, resistance, dt);
      if ((soc <= 0 && currentA >= 0) || (soc >= 1 && currentA <= 0)) cutoff = true;
      const e = actualPowerW * dt / 3.6e6;
      netEnergyKWh += e;
      if (e >= 0) dischargedEnergyKWh += e; else recoveredEnergyKWh += -e;
    }
  }

  const limitedFraction = out.powerLimited.reduce((a, b) => a + b, 0) / Math.max(1, out.powerLimited.length);
  const summary = {
    cell,
    prior,
    packNominal,
    finalSoc: last(out.soc, 0),
    finalSoh: last(out.soh, 1),
    finalTemperatureC: last(out.temperatureC, config.thermal.initialTempC),
    maxTemperatureC: Math.max(...out.temperatureC),
    minCellVoltageV: Math.min(...out.cellVoltageV),
    maxCellVoltageV: Math.max(...out.cellVoltageV),
    peakDischargeKW: Math.max(...out.actualPackPowerKW),
    peakRegenKW: Math.min(...out.actualPackPowerKW),
    netEnergyKWh,
    dischargedEnergyKWh,
    recoveredEnergyKWh,
    maxCRate: Math.max(...out.cRate),
    maxPlatingRisk: Math.max(...out.platingRisk),
    limitedFraction,
    cutoff
  };

  if (config.scenario.type === 'reference-1c' && cell.id === 'ae-nmc111-pouch-12p5ah' && datasets.nmcReference) {
    const errors = datasets.nmcReference.timeS.map((t, j) => {
      const idx = nearestIndex(out.timeS, t);
      return out.cellVoltageV[idx] - datasets.nmcReference.voltageV[j];
    });
    summary.referenceRmseV = rms(errors);
    summary.referenceMaxAbsErrorV = Math.max(...errors.map(Math.abs));
  }

  return { config, out, summary };
}


